 function button(text,fn,id,{disabled=false,pressed}={}){const b=el('button',text);b.type='button';b.dataset.key=id||text;b.disabled=disabled;if(pressed!=null)b.setAttribute('aria-pressed',pressed);b.onclick=fn;return b;}
 function row(...items){const d=el('div',null,'depth-row');d.append(...items);return d;}
