 function metric(label,value,id){const d=el('div',null,'depth-metric'),v=el('b',value);if(id)v.dataset.metric=id;d.append(el('span',label),v);return d;}
 function tabs(names){const n=el('nav',null,'depth-tabs');n.setAttribute('aria-label',section+' sections');for(const name of names)n.append(button(name,()=>{tab=name;filter='';error='';render();},'tab-'+name,{pressed:tab===name}));return n;}
