 function undo(message,type,p){host.toast(message,()=>send(type,p));}
 function guarded(id,label,fn){return button(arm===id?'Confirm within 2s':label,()=>{if(arm===id){clearArm();fn();}else{clearArm();arm=id;armTimer=setTimeout(()=>{arm=null;armTimer=null;if(opened)render();},2000);render();}},id,{disabled:Boolean(job)});}
