 function open(name,from){section=categories.includes(name)?name:'Dev';tab='Overview';filter='';error='';pair=null;clearArm();if(!opened)host.show(from);opened=true;render();panel.querySelector('[data-key="nav-'+section+'"]')?.focus({preventScroll:true});schedule();}
