   const item=card(d.name,hint(d.kind+' · '+(d.connected?'Connected · '+d.battery+'% battery':d.paired?'Paired / disconnected':'Available to pair')),actions);if(pair===d.id){item.append(hint(d.code?'Compare this code on the keyboard: '+d.code:'Put this device into pairing mode.'),row(button('Confirm pairing',()=>{pair=null;run('Pairing '+d.name,()=>model.send('bluetooth.connect',{id:d.id}));},'bt-confirm'),button('Cancel',()=>{pair=null;render();},'bt-pair-cancel')));}body.append(item);
