  body.append(card('Delivery rules',...['Build','Dev','System'].map(app=>row(el('span',app),button(n.muted.includes(app)?'Unmute alerts':'Mute alerts',()=>send('notifications.mute',{app}),'notification-mute-'+app,{pressed:n.muted.includes(app)})))));
