 function drawSystemGraph(){const host=body.querySelector('[data-system-graph]');if(!host)return;const data=s.system.history.filter(x=>x.at>=s.system.elapsed-range),ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),line=document.createElementNS(ns,'polyline');svg.setAttribute('viewBox','0 0 500 80');svg.setAttribute('role','img');svg.setAttribute('aria-label','CPU history over the last '+range+' seconds; 0 to 100 percent');line.setAttribute('points',data.map(x=>((x.at-Math.max(0,s.system.elapsed-range))/range*500)+','+(80-x.cpu*.8)).join(' '));svg.append(line);host.replaceChildren(svg,hint('0–100% CPU · most recent '+range+' seconds'));}
